<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { Calendar,Plus,Refresh,Search } from '@element-plus/icons-vue'
import { api,apiErrorMessage,ensureCsrf } from '../services/api'
import type { CandidateContact,Company,HrNotification,InterviewDetail,InterviewSchedule,InterviewSlot,InterviewStatus,MockNotificationOutcome } from '../types'

interface SlotForm{startsAt:string;endsAt:string}
const loading=ref(true),loadError=ref(''),interviews=ref<InterviewSchedule[]>([]),candidates=ref<CandidateContact[]>([]),companies=ref<Company[]>([])
const keyword=ref(''),companyFilter=ref(''),statusFilter=ref<InterviewStatus|''>('')
const dialogOpen=ref(false),rescheduling=ref<InterviewSchedule|null>(null),saving=ref(false),formError=ref('')
const form=reactive<{contactId:string;timezone:string;mockNotificationOutcome:MockNotificationOutcome;slots:SlotForm[]}>({contactId:'',timezone:'Asia/Shanghai',mockNotificationOutcome:'SUCCESS',slots:[]})
const detailOpen=ref(false),detailLoading=ref(false),detail=ref<InterviewDetail|null>(null),acting=ref(false),mockOutcome=ref<MockNotificationOutcome>('SUCCESS')
const eligibleCandidates=computed(()=>candidates.value.filter(c=>c.privacyStatus==='ACTIVE'&&['QUALIFIED','CONTACTING'].includes(c.status)))
const stats=computed(()=>({total:interviews.value.length,proposing:interviews.value.filter(i=>i.status==='PROPOSING').length,confirmed:interviews.value.filter(i=>i.status==='CONFIRMED').length,attention:interviews.value.filter(i=>i.status==='RESCHEDULE_REQUIRED').length}))
const statusLabels:Record<InterviewStatus,string>={PROPOSING:'待候选人确认',CONFIRMED:'已确认',RESCHEDULE_REQUIRED:'需重新约定',CANCELLED:'已取消'}
function statusType(s:InterviewStatus){return ({PROPOSING:'warning',CONFIRMED:'success',RESCHEDULE_REQUIRED:'danger',CANCELLED:'info'} as const)[s]}
function pad(v:number){return String(v).padStart(2,'0')}
function localInput(date:Date){return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`}
function defaultSlots(){const first=new Date();first.setDate(first.getDate()+2);first.setHours(10,0,0,0);const second=new Date(first);second.setDate(second.getDate()+1);return [first,second].map(start=>({startsAt:localInput(start),endsAt:localInput(new Date(start.getTime()+60*60*1000))}))}
async function loadData(){loading.value=true;loadError.value='';try{const [ir,cr,or]=await Promise.all([api.get<InterviewSchedule[]>('/interviews',{params:{keyword:keyword.value.trim()||undefined,companyId:companyFilter.value||undefined,status:statusFilter.value||undefined}}),api.get<CandidateContact[]>('/candidate-contacts'),api.get<Company[]>('/organization/companies')]);interviews.value=ir.data;candidates.value=cr.data;companies.value=or.data}catch(e){loadError.value=apiErrorMessage(e,'面试安排加载失败')}finally{loading.value=false}}
function openCreate(){rescheduling.value=null;Object.assign(form,{contactId:eligibleCandidates.value[0]?.id??'',timezone:'Asia/Shanghai',mockNotificationOutcome:'SUCCESS',slots:defaultSlots()});formError.value='';dialogOpen.value=true}
function openReschedule(schedule:InterviewSchedule){rescheduling.value=schedule;Object.assign(form,{contactId:schedule.contact.id,timezone:schedule.timezone,mockNotificationOutcome:schedule.mockNotificationOutcome,slots:defaultSlots()});formError.value='';dialogOpen.value=true}
function payloadSlots(){return form.slots.map(slot=>({startsAt:new Date(slot.startsAt).toISOString(),endsAt:new Date(slot.endsAt).toISOString()}))}
async function save(){if(!form.contactId||!form.timezone.trim()||form.slots.length<2||form.slots.some(s=>!s.startsAt||!s.endsAt)){formError.value='请选择候选人、填写时区并完整提供至少两个候选时间';return}saving.value=true;formError.value='';try{await ensureCsrf();const {data}=rescheduling.value?await api.post(`/interviews/${rescheduling.value.id}/reschedule`,{slots:payloadSlots()}):await api.post('/interviews',{contactId:form.contactId,timezone:form.timezone,mockNotificationOutcome:form.mockNotificationOutcome,slots:payloadSlots()});ElMessage.success(rescheduling.value?'新一轮候选时间已发出':'面试候选时间已创建');dialogOpen.value=false;await loadData();await openDetail(data)}catch(e){formError.value=apiErrorMessage(e,'面试安排保存失败')}finally{saving.value=false}}
async function openDetail(schedule:InterviewSchedule){detailOpen.value=true;detailLoading.value=true;try{detail.value=(await api.get<InterviewDetail>(`/interviews/${schedule.id}`)).data;mockOutcome.value=detail.value.schedule.mockNotificationOutcome}catch(e){ElMessage.error(apiErrorMessage(e,'面试详情加载失败'))}finally{detailLoading.value=false}}
async function refreshDetail(){if(detail.value)await openDetail(detail.value.schedule)}
async function confirmSlot(slot:InterviewSlot){if(!detail.value)return;acting.value=true;try{await ensureCsrf();const key=`confirm-${detail.value.schedule.id}-${Date.now()}-${crypto.randomUUID()}`;const {data}=await api.post(`/interviews/${detail.value.schedule.id}/confirm/${slot.id}`,null,{headers:{'Idempotency-Key':key}});if(data.result==='CONFIRMED')ElMessage.success(data.notification?.status==='SENT'?'面试已确认，HR 通知已送达':'面试已确认，但 HR 通知失败');else ElMessage.warning(data.result==='CONFLICT'?'负责 HR 时间冲突，请重新约定':'候选时间已过期，请重新约定');await refreshDetail();await loadData()}catch(e){ElMessage.error(apiErrorMessage(e,'面试时间确认失败'))}finally{acting.value=false}}
async function saveMockOutcome(){if(!detail.value)return;acting.value=true;try{await ensureCsrf();await api.patch(`/interviews/${detail.value.schedule.id}/notification-outcome`,{outcome:mockOutcome.value});ElMessage.success('Mock 通知结果已更新');await refreshDetail();await loadData()}catch(e){ElMessage.error(apiErrorMessage(e,'Mock 配置更新失败'))}finally{acting.value=false}}
async function retryNotification(item:HrNotification){if(!detail.value)return;acting.value=true;try{await ensureCsrf();const key=`notify-${item.id}-${Date.now()}-${crypto.randomUUID()}`;const {data}=await api.post(`/interviews/${detail.value.schedule.id}/notifications/${item.id}/retry`,null,{headers:{'Idempotency-Key':key}});ElMessage.success(data.notification.status==='SENT'?'HR 通知重试成功':'HR 通知重试仍失败');await refreshDetail()}catch(e){ElMessage.error(apiErrorMessage(e,'HR 通知重试失败'))}finally{acting.value=false}}
async function cancelSchedule(){if(!detail.value)return;try{await ElMessageBox.confirm('取消后将保留时间与通知历史，且不能恢复。','确认取消',{type:'warning',confirmButtonText:'确认取消'});await ensureCsrf();await api.post(`/interviews/${detail.value.schedule.id}/cancel`);ElMessage.success('面试安排已取消');await refreshDetail();await loadData()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(apiErrorMessage(e,'取消失败'))}}
function formatTime(value:string,timezone:string){return new Intl.DateTimeFormat('zh-CN',{timeZone:timezone,dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}
onMounted(loadData)
</script>

<template><div class="page-shell"><header class="page-heading"><div><h1>面试协调</h1><p>提供带时区的候选时间，处理冲突、过期与重新约定，并幂等通知负责 HR。</p></div><el-button type="primary" :icon="Plus" @click="openCreate">安排面试</el-button></header><el-alert title="当前仅使用 Mock Notification Gateway；确认面试不会连接真实日历或邮件服务。" type="info" :closable="false" show-icon class="gateway-alert"/><div v-if="loading" class="surface-panel skeleton-stack"><el-skeleton :rows="7" animated/></div><div v-else-if="loadError" class="surface-panel error-state"><el-icon><Refresh/></el-icon><strong>面试安排暂时无法加载</strong><span>{{loadError}}</span><el-button @click="loadData">重新加载</el-button></div><template v-else><div class="interview-metrics"><div><span>面试安排</span><strong>{{stats.total}}</strong></div><div><span>待确认</span><strong>{{stats.proposing}}</strong></div><div><span>已确认</span><strong>{{stats.confirmed}}</strong></div><div><span>需重约</span><strong>{{stats.attention}}</strong></div></div><section class="surface-panel interviews-panel"><div class="section-title-row interviews-title"><div><h2>面试列表</h2><p>所有时间以安排时指定的 IANA 时区展示</p></div><div class="filters"><el-input v-model="keyword" clearable placeholder="搜索候选人、职位或负责 HR" :prefix-icon="Search" @keyup.enter="loadData"/><el-select v-model="companyFilter" clearable placeholder="全部企业" @change="loadData"><el-option v-for="c in companies" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-select v-model="statusFilter" placeholder="全部状态" @change="loadData"><el-option label="全部状态" value=""/><el-option v-for="(label,value) in statusLabels" :key="value" :label="label" :value="value"/></el-select><el-button @click="loadData">查询</el-button></div></div><div v-if="!interviews.length" class="empty-state"><el-icon><Calendar/></el-icon><strong>还没有面试安排</strong><span>已通过或沟通中的候选人可以进入面试时间确认。</span><el-button type="primary" @click="openCreate">安排面试</el-button></div><template v-else><el-table :data="interviews" class="interviews-table"><el-table-column label="候选人 / 企业" min-width="190"><template #default="{row}"><strong>{{row.contact.candidateName}}</strong><div class="muted">{{row.contact.companyName}}</div></template></el-table-column><el-table-column label="职位" min-width="170" prop="contact.jobTitle"/><el-table-column label="确认时间" min-width="210"><template #default="{row}">{{row.confirmedSlot?formatTime(row.confirmedSlot.startsAt,row.timezone):`${row.currentSlots.length} 个候选时间`}}<div class="muted">{{row.timezone}} · 第 {{row.currentRound}} 轮</div></template></el-table-column><el-table-column label="负责 HR" min-width="130" prop="ownerHr.displayName"/><el-table-column label="状态" width="130"><template #default="{row}"><el-tag :type="statusType(row.status)">{{statusLabels[row.status as InterviewStatus]}}</el-tag></template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openDetail(row as InterviewSchedule)">协调</el-button></template></el-table-column></el-table><div class="interview-cards"><article v-for="item in interviews" :key="item.id"><header><div><strong>{{item.contact.candidateName}}</strong><span>{{item.contact.jobTitle}}</span></div><el-tag :type="statusType(item.status)" size="small">{{statusLabels[item.status]}}</el-tag></header><dl><div><dt>企业</dt><dd>{{item.contact.companyName}}</dd></div><div><dt>负责 HR</dt><dd>{{item.ownerHr.displayName}}</dd></div><div><dt>时间</dt><dd>{{item.confirmedSlot?formatTime(item.confirmedSlot.startsAt,item.timezone):`${item.currentSlots.length} 个候选时间`}}</dd></div><div><dt>时区</dt><dd>{{item.timezone}}</dd></div></dl><el-button type="primary" plain @click="openDetail(item)">打开协调台</el-button></article></div></template></section></template>

<el-dialog v-model="dialogOpen" :title="rescheduling?'重新约定面试':'安排面试'" width="720px"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top"><div class="form-grid"><el-form-item label="候选人 / 职位"><el-select v-model="form.contactId" filterable :disabled="!!rescheduling"><el-option v-for="c in eligibleCandidates" :key="c.id" :label="`${c.displayName} · ${c.jobPosition.title}（${c.company.name}）`" :value="c.id"/></el-select></el-form-item><el-form-item label="IANA 时区"><el-input v-model="form.timezone" :disabled="!!rescheduling"/></el-form-item><el-form-item v-if="!rescheduling" label="Mock HR 通知结果"><el-select v-model="form.mockNotificationOutcome"><el-option label="成功" value="SUCCESS"/><el-option label="失败" value="FAILURE"/></el-select></el-form-item></div><div v-for="(slot,index) in form.slots" :key="index" class="slot-row"><strong>候选时间 {{index+1}}</strong><el-form-item :label="`候选时间 ${index+1} 开始`"><el-input v-model="slot.startsAt" type="datetime-local"/></el-form-item><el-form-item :label="`候选时间 ${index+1} 结束`"><el-input v-model="slot.endsAt" type="datetime-local"/></el-form-item></div><el-button v-if="form.slots.length<5" text type="primary" @click="form.slots.push(defaultSlots()[0]!)">增加候选时间</el-button></el-form><template #footer><el-button @click="dialogOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">{{rescheduling?'发出新一轮时间':'创建面试安排'}}</el-button></template></el-dialog>

<el-drawer v-model="detailOpen" :title="`${detail?.schedule.contact.candidateName??''} · 面试协调台`" size="min(760px,96vw)"><el-skeleton v-if="detailLoading" :rows="8" animated/><template v-else-if="detail"><section class="schedule-summary"><div><el-tag :type="statusType(detail.schedule.status)">{{statusLabels[detail.schedule.status]}}</el-tag><strong>{{detail.schedule.contact.jobTitle}} · {{detail.schedule.contact.companyName}}</strong><span>负责 HR：{{detail.schedule.ownerHr.displayName}} · {{detail.schedule.timezone}}</span></div><div class="summary-actions"><el-button v-if="['CONFIRMED','RESCHEDULE_REQUIRED'].includes(detail.schedule.status)" type="warning" @click="openReschedule(detail.schedule)">重新约定</el-button><el-button v-if="detail.schedule.status!=='CANCELLED'" type="danger" plain @click="cancelSchedule">取消安排</el-button></div></section><el-tabs><el-tab-pane label="候选时间"><div class="slot-list"><article v-for="slot in detail.slots" :key="slot.id" :class="{historical:slot.roundNumber!==detail.schedule.currentRound}"><div><strong>第 {{slot.roundNumber}} 轮 · {{formatTime(slot.startsAt,detail.schedule.timezone)}}</strong><span>至 {{formatTime(slot.endsAt,detail.schedule.timezone)}}</span></div><el-tag :type="slot.status==='CONFIRMED'?'success':slot.status==='AVAILABLE'?'warning':'info'">{{slot.status}}</el-tag><el-button v-if="slot.roundNumber===detail.schedule.currentRound&&slot.status==='AVAILABLE'&&['PROPOSING','RESCHEDULE_REQUIRED'].includes(detail.schedule.status)" type="primary" :loading="acting" @click="confirmSlot(slot)">候选人确认此时间</el-button></article></div></el-tab-pane><el-tab-pane label="HR 通知"><div class="mock-config"><el-select v-model="mockOutcome"><el-option label="Mock 成功" value="SUCCESS"/><el-option label="Mock 失败" value="FAILURE"/></el-select><el-button :loading="acting" @click="saveMockOutcome">保存 Mock 结果</el-button></div><el-empty v-if="!detail.notifications.length" description="确认面试后生成 HR 通知"/><div v-else class="notification-list"><article v-for="item in detail.notifications" :key="item.id"><header><strong>第 {{item.confirmationRound}} 轮 · {{item.recipientName}}</strong><el-tag :type="item.status==='SENT'?'success':item.status==='FAILED'?'danger':'warning'">{{item.status}}</el-tag></header><p>{{item.lastError||'通知已成功送达'}}</p><footer><span>尝试 {{item.attemptCount}} 次</span><el-button v-if="item.status==='FAILED'" type="primary" size="small" :loading="acting" @click="retryNotification(item)">重试通知</el-button></footer><ul><li v-for="attempt in item.attempts" :key="attempt.id">{{formatTime(attempt.attemptedAt,detail.schedule.timezone)}} · {{attempt.status}} · {{attempt.message}}</li></ul></article></div></el-tab-pane></el-tabs></template></el-drawer></div></template>

<style scoped>.gateway-alert{margin-bottom:20px}.interview-metrics{display:grid;grid-template-columns:repeat(4,1fr);margin-bottom:20px;border:1px solid var(--border);border-radius:12px;background:var(--surface);overflow:hidden}.interview-metrics div{padding:18px 22px;border-right:1px solid var(--border)}.interview-metrics div:last-child{border:0}.interview-metrics span,.interview-metrics strong{display:block}.interview-metrics span,.muted{color:var(--text-secondary);font-size:12px}.interview-metrics strong{margin-top:5px;font-size:24px}.interviews-panel{overflow:hidden}.interviews-title{align-items:flex-end}.filters{display:grid;grid-template-columns:minmax(240px,1fr) 150px 150px auto;gap:8px}.interviews-table{width:100%}.interview-cards{display:none}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}.form-grid .el-select{width:100%}.slot-row{display:grid;grid-template-columns:110px 1fr 1fr;gap:12px;align-items:center;padding:12px 0;border-top:1px solid var(--border)}.slot-row .el-form-item{margin:0}.schedule-summary{display:flex;justify-content:space-between;gap:16px;padding:16px;border:1px solid var(--border);border-radius:10px}.schedule-summary strong,.schedule-summary span{display:block;margin-top:8px}.schedule-summary span{color:var(--text-secondary);font-size:12px}.summary-actions{display:flex;align-items:flex-start;gap:8px}.slot-list,.notification-list{display:grid;gap:12px}.slot-list article{display:grid;grid-template-columns:1fr auto auto;gap:12px;align-items:center;padding:14px;border:1px solid var(--border);border-radius:10px}.slot-list article.historical{opacity:.65}.slot-list span{display:block;margin-top:5px;color:var(--text-secondary);font-size:12px}.mock-config{display:flex;gap:8px;margin-bottom:16px}.notification-list article{padding:15px;border:1px solid var(--border);border-radius:10px}.notification-list header,.notification-list footer{display:flex;justify-content:space-between;gap:12px}.notification-list p,.notification-list ul{color:var(--text-secondary);font-size:13px}.notification-list ul{padding-left:18px;line-height:1.7}
@media(max-width:1150px){.interviews-title{display:grid}.filters{width:100%}}
@media(max-width:720px){.interview-metrics{grid-template-columns:repeat(2,1fr)}.interview-metrics div:nth-child(2){border-right:0}.interview-metrics div:nth-child(-n+2){border-bottom:1px solid var(--border)}.filters{grid-template-columns:1fr}.interviews-table{display:none}.interview-cards{display:grid;gap:12px;padding:14px}.interview-cards article{padding:16px;border:1px solid var(--border);border-radius:10px}.interview-cards header{display:flex;justify-content:space-between;gap:12px}.interview-cards header span{display:block;margin-top:5px;color:var(--text-secondary);font-size:12px}.interview-cards dl{display:grid;gap:10px;margin:16px 0}.interview-cards dl div{display:grid;grid-template-columns:72px 1fr}.interview-cards dt{color:var(--text-secondary)}.interview-cards dd{margin:0}.interview-cards .el-button{width:100%;min-height:42px}.form-grid{grid-template-columns:1fr}.slot-row{grid-template-columns:1fr}.schedule-summary{display:grid}.summary-actions{display:grid;grid-template-columns:1fr}.summary-actions .el-button{margin:0}.slot-list article{grid-template-columns:1fr auto}.slot-list article .el-button{grid-column:1/-1}.mock-config{display:grid}}</style>
